/* Feature implementation based on the signed-in reference audit, 24 Nov 2026. */
const legacyOpenForm=openForm,legacyRender=render,legacySettings=settings;
let viewMode='table',dateWindow='This month',fromDate='',toDate='',category='All',insurerFilter='All',spFilter='All',flagFilter='All',contactTab='All',compactRates=false,selectedRates=[],collapsedStages=new Set(),marketingTab='Posters';
const missingService='Not connected — your own authenticated backend / provider is required.';
function connectionNote(){return '<div class="storage-status">'+I('lock')+' Browser workspace · records and documents are saved on this device. Live services are not connected.</div>'}
function emptyCard(title,text,action=''){return `<div class="empty"><h3>${title}</h3><p>${text}</p>${action}</div>`}
function inlineSearch(placeholder){return `<div class="searchbox">${I('search')}<input placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(query)}" oninput="query=this.value;refreshParityResults()"></div>`}
function setFilter(key,value){if(key==='product')productFilter=value;else if(key==='window')dateWindow=value;else if(key==='insurer')insurerFilter=value;else if(key==='flag')flagFilter=value;else if(key==='sp')spFilter=value;else if(key==='category')category=value;else if(key==='contact')contactTab=value;render()}
function pillTabs(items,selected,callback){return `<div class="tabs">${items.map(v=>`<button class="${v===selected?'active':''}" onclick="${callback}('${v}')">${esc(v)}</button>`).join('')}</div>`}
function productTabs(){return pillTabs(['All','Health','Motor','SME','Life','Term','Travel','Investment','Mutual Fund'],category,'setProductCategory')}
function setProductCategory(v){category=v;render()}
function pageActions(kind){return btn('Excel',`exportExcel('${kind}')`,'download')+btn('CSV',`exportRows('${kind}')`,'download')+btn('Print / Save PDF',`printRecords('${kind}')`,'file')}
function viewControls(){return `<div class="view-controls">${['cards','list','table'].map(v=>`<button class="${viewMode===v?'primary':''}" onclick="viewMode='${v}';render()">${I(v==='cards'?'grid':'file')}${v}</button>`).join('')}</div>`}
function fiscalYear(date){let d=new Date(date+'T00:00:00');return d.getMonth()<3?d.getFullYear()-1:d.getFullYear()}
let bookingFY='All',bookingMonthFilter='All';
function parityBookings(){return db.bookings.filter(b=>([b.name,b.id,b.policyNumber,b.insurer,b.phone].join(' ').toLowerCase().includes(query.toLowerCase()))&&(productFilter==='All products'||b.product===productFilter)&&(bookingFY==='All'||fiscalYear(b.date)===+bookingFY)&&(bookingMonthFilter==='All'||new Date(b.date+'T00:00:00').getMonth()===+bookingMonthFilter))}
function bookingStats(rows){return {premium:rows.reduce((s,b)=>s+amount(b.premium),0),received:rows.reduce((s,b)=>s+amount(b.pointsReceived),0),daily:rows.reduce((s,b)=>s+amount(b.dailyPointsDue),0),cycle:rows.reduce((s,b)=>s+amount(b.cyclePointsDue),0),issued:rows.filter(b=>b.status==='Issued').length,gross:rows.reduce((s,b)=>s+amount(b.grossPoints),0)}}
bookings=function(){let rows=parityBookings(),s=bookingStats(rows),years=[...new Set(db.bookings.map(b=>fiscalYear(b.date)))].sort((a,b)=>b-a);return heading('BOOKINGS','My bookings','Filter policies, inspect documents and track recorded points.',pageActions('bookings')+btn('Add My Booking',"mapBooking()",'plus',true))+connectionNote()+`<div class="metrics six">${metric('Premium',rupee(s.premium),'trend','Booked')}${metric('Points received',s.received+' pts','check','Recorded received')}${metric('Daily points due',s.daily+' pts','clock','Recorded due')}${metric('Cycle points due',s.cycle+' pts','calendar','Recorded due')}${metric('Policies',s.issued,'shield','Issued')}${metric('Gross points',s.gross+' pts','wallet','Recorded total')}</div><div class="toolbar"><select aria-label="Financial year" onchange="bookingFY=this.value;render()"><option value="All">All financial years</option>${years.map(y=>`<option value="${y}" ${String(y)===bookingFY?'selected':''}>FY${String(y).slice(-2)}–${String(y+1).slice(-2)}</option>`).join('')}</select><select aria-label="Booking month" onchange="bookingMonthFilter=this.value;render()"><option value="All">All months</option>${Array.from({length:12},(_,i)=>`<option value="${i}" ${String(i)===bookingMonthFilter?'selected':''}>${new Date(2026,i,1).toLocaleString('en',{month:'long'})}</option>`).join('')}</select><select aria-label="Booking product" onchange="productFilter=this.value;render()">${optionsHTML(['All products',...new Set(db.bookings.map(b=>b.product))],productFilter,false)}</select>${inlineSearch('Search customer, mobile, policy or insurer…')}${viewControls()}</div><details class="card summary-panel"><summary>Product summary</summary><div class="tablewrap"><table><thead><tr><th>Product</th><th>Policies</th><th>Premium</th><th>Gross points</th></tr></thead><tbody>${[...new Set(rows.map(b=>b.product))].map(p=>{let r=rows.filter(b=>b.product===p),t=bookingStats(r);return `<tr><td>${esc(p)}</td><td>${r.length}</td><td>${rupee(t.premium)}</td><td>${t.gross}</td></tr>`}).join('')||'<tr><td colspan="4">No data in this view</td></tr>'}</tbody></table></div></details><section id="results">${bookingResults(rows)}</section>`}
function bookingResults(rows=parityBookings()){if(!rows.length)return '<section class="card">'+emptyCard('No bookings found','Add a policy copy to start your approval queue.',btn('Add My Booking',"mapBooking()",'plus',true))+'</section>';if(viewMode==='cards')return `<div class="record-grid">${rows.map(b=>`<article class="card pad"><span class="badge">${esc(b.status)}</span><h3>${esc(b.name)}</h3><p class="subtle">${esc(b.product)} · ${esc(b.insurer||'Insurer not recorded')}</p><div class="metricvalue">${rupee(b.premium)}</div><p class="subtle">${esc(b.policyNumber||b.id)}<br>${esc(b.date)}</p>${btn('View details',`viewBooking('${b.id}')`,'file')}</article>`).join('')}</div>`;return `<section class="card">${recentTable(rows)}</section>`}
function mapBooking(){modal('Map My Lead',`<p>Upload a policy copy, verify the customer and record a request for approval.</p><div class="notice">AI extraction and an approver are not connected. The file is stored on this device; the record remains “Pending approval”.</div><form onsubmit="event.preventDefault();saveMappedBooking(this)"><div class="formgrid">${fieldHTML(F('policyCopy','Policy copy','file',true))}${fieldHTML(F('name','Customer name','text',true))}${fieldHTML(F('phone','Customer mobile','tel',true))}${fieldHTML(F('product','Product','select',true,Object.keys(WORKFLOWS)))}${fieldHTML(F('insurer','Insurer'))}${fieldHTML(F('caseType','Type','select',true,['Fresh','Renewal','Port']))}${fieldHTML(F('policyNumber','Policy number'))}${fieldHTML(F('premium','Premium (₹)','number',true))}${fieldHTML(F('date','Policy start date','date',true),dateISO())}${fieldHTML(F('renewal','Policy expiry date','date',true))}</div><div class="modalfoot"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">Save approval request</button></div></form>`)}
async function saveMappedBooking(form){try{let d=Object.fromEntries(new FormData(form));if(!validPhone(d.phone))throw Error('Enter a valid mobile number');if(d.renewal<=d.date)throw Error('Expiry must be after start date');let file=form.elements.policyCopy.files[0];if(!file)throw Error('Upload the policy copy');let attachment=await persistFile(file);db.bookings.unshift({...d,policyCopy:attachment,id:uid('POL'),phone:normalisePhone(d.phone),premium:amount(d.premium),status:'Pending approval',date:d.date});activityLog('Approval request saved for '+d.name);closeModal();go('bookings');toast('Saved locally — approval service not connected')}catch(e){toast(e.message)}}
openForm=function(type,product='Health',cid=''){if(type==='lead')return startLead(product,cid);if(type==='booking')return mapBooking();if(type==='contact'||type==='prospect')return contactForm(type==='prospect');return legacyOpenForm(type,product,cid)};
viewBooking=function(id){let b=db.bookings.find(b=>b.id===id);if(!b)return;modal('Policy record',`<span class="badge">${esc(b.status)}</span><h2>${esc(b.name)}</h2><dl class="review-list">${Object.entries(b).filter(([k,v])=>['product','insurer','premium','policyNumber','phone','date','renewal','caseType','policyCopy','pointsReceived','grossPoints'].includes(k)&&typeof v!=='undefined').map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${k==='premium'?rupee(v):reviewValue(v)}</dd></div>`).join('')}</dl><p class="subtle">This is your workspace record. An insurer must confirm actual issuance.</p><div class="modalfoot">${btn('Export record',`downloadRecord('${id}')`,'download')}${btn('Close','closeModal()')}</div>`)};
function inDateWindow(value,windowName=dateWindow){if(!value)return false;let d=value.slice(0,10),today=dateISO(),now=new Date(today+'T12:00:00');if(windowName==='All')return true;if(windowName==='Expired')return d<today;if(windowName==='Today')return d===today;if(windowName==='Custom')return (!fromDate||d>=fromDate)&&(!toDate||d<=toDate);let delta={'Last month':-1,'This month':0,'Next month':1}[windowName]||0,month=new Date(now.getFullYear(),now.getMonth()+delta,1);return d.slice(0,7)===`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}`}
function renewalRows(){return db.bookings.filter(b=>inDateWindow(b.renewal)&&(category==='All'||b.product===category)&&(insurerFilter==='All'||b.insurer===insurerFilter)&&(spFilter==='All'||b.serviceProvider===spFilter)&&(flagFilter==='All'||(b.renewed?'Renewed':b.flag||'Follow-up')===flagFilter)&&[b.name,b.phone,b.policyNumber,b.id].join(' ').toLowerCase().includes(query.toLowerCase()))}
function renewalTotals(rows){let cp=rows.reduce((s,b)=>s+amount(b.commissionablePremium??b.premium),0),won=rows.filter(b=>b.renewed),lost=rows.filter(b=>b.flag==='Lost');return {cp,open:rows.filter(b=>!b.renewed&&b.flag!=='Lost'),won,lost,achieved:won.reduce((s,b)=>s+amount(b.achievedCP??b.premium),0),lostCP:lost.reduce((s,b)=>s+amount(b.commissionablePremium??b.premium),0),retention:rows.length?Math.round(won.length/rows.length*100):0}}
renewals=function(){let rows=renewalRows(),s=renewalTotals(rows);return heading('RENEWAL BOARD','My renewals','Prioritise follow-ups, track flags and retain your customers.',pageActions('renewals'))+connectionNote()+`<div class="metrics six">${metric('Commissionable premium',rupee(s.cp),'shield',rows.length+' policies')}${metric('Follow-up',s.open.length,'phone','Open')}${metric('Achieved CP',rupee(s.achieved),'check',s.won.length+' renewed')}${metric('Lost CP',rupee(s.lostCP),'close',s.lost.length+' lost')}${metric('Network',new Set(rows.map(b=>b.agent).filter(Boolean)).size,'users','Recorded agents')}${metric('Retention',s.retention+'%','renew','For selected filters')}</div>${pillTabs(['Expired','Today','Last month','This month','Next month','Custom','All'],dateWindow,"setDateWindow")}<div class="toolbar">${dateWindow==='Custom'?`<input type="date" aria-label="From date" value="${fromDate}" onchange="fromDate=this.value;render()"><input type="date" aria-label="To date" value="${toDate}" onchange="toDate=this.value;render()">`:''}${viewControls()}${btn('WhatsApp summary',"shareSummary('renewals')",'phone')}${btn('Reset filters','resetFilters()','renew')}</div>${productTabs()}<div class="toolbar"><select aria-label="Renewal flag" onchange="setFilter('flag',this.value)">${optionsHTML(['All','Follow-up','Overdue','Renewed','Lost'],flagFilter,false)}</select><select aria-label="Insurer" onchange="setFilter('insurer',this.value)">${optionsHTML(['All',...new Set(db.bookings.map(b=>b.insurer).filter(Boolean))],insurerFilter,false)}</select><select aria-label="Service provider" onchange="setFilter('sp',this.value)">${optionsHTML(['All',...new Set(db.bookings.map(b=>b.serviceProvider).filter(Boolean))],spFilter,false)}</select>${inlineSearch('Search name, mobile, policy…')}</div><section id="results">${renewalResults()}</section>`}
function setDateWindow(v){dateWindow=v;render()}
function resetFilters(){dateWindow='This month';fromDate='';toDate='';category='All';insurerFilter='All';spFilter='All';flagFilter='All';query='';render()}
renewalResults=function(){let rows=renewalRows();if(!rows.length)return '<section class="card">'+emptyCard('No policies found','Try a different date range or filter.')+'</section>';return `<section class="${viewMode==='cards'?'record-grid':'card tablewrap'}">${viewMode==='cards'?rows.map(b=>`<article class="card pad"><span class="badge">${esc(b.renewal)}</span><h3>${esc(b.name)}</h3><p class="subtle">${esc(b.product)} · ${esc(b.insurer||'')}</p><strong>${rupee(b.premium)}</strong><p>${renewalFlagControl(b)}</p></article>`).join(''):`<table><thead><tr><th>Expiry</th><th>Customer</th><th>Product / insurer</th><th>Agent</th><th>Total premium</th><th>Old CP</th><th>Achieved CP</th><th>Policy #</th><th>Flag</th><th>Actions</th></tr></thead><tbody>${rows.map(b=>`<tr><td>${esc(b.renewal)}</td><td>${esc(b.name)}<div class="subtle">${esc(b.phone||'')}</div></td><td>${esc(b.product)}<div class="subtle">${esc(b.insurer||'')}</div></td><td>${esc(b.agent||workspace.profile.name)}</td><td>${rupee(b.premium)}</td><td>${rupee(b.commissionablePremium??b.premium)}</td><td>${rupee(b.achievedCP||0)}</td><td>${esc(b.policyNumber||b.id)}</td><td>${renewalFlagControl(b)}</td><td>${btn('Policy',`viewBooking('${b.id}')`,'file')}${btn('Draft reminder',`reminder('${b.id}')`,'phone')}</td></tr>`).join('')}</tbody></table>`}</section>`}
function renewalFlagControl(b){return `<select aria-label="Flag for ${esc(b.name)}" onchange="setRenewalFlag('${b.id}',this.value)">${optionsHTML(['Follow-up','Overdue','Renewed','Lost'],b.renewed?'Renewed':b.flag||'Follow-up',false)}</select>`}
function setRenewalFlag(id,flag){let b=db.bookings.find(b=>b.id===id);b.flag=flag;b.renewed=flag==='Renewed';b.achievedCP=b.renewed?amount(b.commissionablePremium??b.premium):0;save();render();toast('Workspace renewal flag updated')}
function reminder(id){let b=db.bookings.find(b=>b.id===id);draftMessage(`Hi ${b.name}, your ${b.product} policy ${b.policyNumber||''} is due for renewal on ${b.renewal}. Would you like me to help review your cover and prepare a renewal quote?`)}
function draftMessage(text){modal('Review message draft',`<p>Edit the text before sharing. No message is sent automatically.</p><textarea id="shareDraft" rows="7" style="width:100%">${esc(text)}</textarea><div class="modalfoot">${btn('Copy text',"copyText(document.querySelector('#shareDraft').value)",'copy')}${btn('Open WhatsApp',"openWhatsApp(document.querySelector('#shareDraft').value)",'phone',true)}</div>`)}
function openWhatsApp(text){window.open('https://wa.me/?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied')}catch{toast('Copy is unavailable. Select and copy the text manually.')}}
function shareSummary(kind){let rows=kind==='renewals'?renewalRows():filteredLeads();draftMessage(`Sigma0Nine ${kind} summary\n${rows.map(b=>`${b.name} · ${b.product} · ${b.renewal||b.status} · ${rupee(b.premium||0)}`).join('\n')||'No matching records.'}`)}
function normalStage(s){return s==='Issued'?'Policy issued':s||'New'}
function filteredLeads(){return db.leads.filter(l=>(category==='All'||l.product===category)&&(filter==='All'||normalStage(l.status)===filter)&&(!fromDate||(l.date||l.createdAt||'').slice(0,10)>=fromDate)&&(!toDate||(l.date||l.createdAt||'').slice(0,10)<=toDate)&&[l.name,l.phone,l.agent,l.product,l.policyNumber].join(' ').toLowerCase().includes(query.toLowerCase()))}
leads=function(prospect=false){if(prospect)return prospectPage();return heading('LEAD PIPELINE','My leads','Track every stage from a new enquiry to won and mapped.',pageActions('leads')+btn('New lead',"go('sell')",'plus',true))+connectionNote()+`<div class="pipeline-summary">${leadStages.map(s=>`<button class="${filter===s?'primary':''}" onclick="filter=filter==='${s}'?'All':'${s}';render()">${s}<strong>${db.leads.filter(l=>normalStage(l.status)===s).length}</strong></button>`).join('')}</div>${productTabs()}<div class="toolbar">${inlineSearch('Search customer, mobile, agent, product, policy…')}<input type="date" aria-label="Lead from date" value="${fromDate}" onchange="fromDate=this.value;render()"><input type="date" aria-label="Lead to date" value="${toDate}" onchange="toDate=this.value;render()">${btn(viewMode==='kanban'?'List':'Kanban',"viewMode=viewMode==='kanban'?'list':'kanban';render()",'grid')}${btn('WhatsApp summary',"shareSummary('leads')",'phone')}</div><div id="results">${leadResults()}</div>`}
leadResults=function(){const rows=filteredLeads();if(viewMode!=='kanban')return `<section class="card tablewrap"><table><thead><tr><th>Customer</th><th>Product</th><th>Stage</th><th>Created</th><th>Details</th></tr></thead><tbody>${rows.map(l=>`<tr><td>${esc(l.name)}<div class="subtle">${esc(l.phone||'')}</div></td><td>${esc(l.product)}</td><td>${stageControl(l)}</td><td>${esc(l.date||l.createdAt?.slice(0,10)||'')}</td><td>${btn('View',`leadDetail('${l.id}')`,'file')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No leads match this view.</td></tr>'}</tbody></table></section>`;return `<div class="kanban parity-kanban">${leadStages.map(s=>`<div class="column ${collapsedStages.has(s)?'stage-collapsed':''}"><button class="column-title" onclick="toggleStage('${s}')">${s}<span>${rows.filter(l=>normalStage(l.status)===s).length}</span></button>${!collapsedStages.has(s)?rows.filter(l=>normalStage(l.status)===s).map(l=>`<article class="leadcard"><span class="badge">${esc(l.product)}</span><h4>${esc(l.name)}</h4><p>${esc(l.phone||'')}<br>${esc(l.date||'')}</p>${stageControl(l)}${btn('View details',`leadDetail('${l.id}')`,'file')}</article>`).join(''):''}</div>`).join('')}</div>`}
function stageControl(l){return `<select aria-label="Stage for ${esc(l.name)}" onchange="moveLead('${l.id}',this.value)">${optionsHTML(leadStages,normalStage(l.status),false)}</select>`}
function toggleStage(s){if(collapsedStages.has(s))collapsedStages.delete(s);else collapsedStages.add(s);render()}
moveLead=function(id,status){let l=db.leads.find(l=>l.id===id);if(!l)return;l.status=status;activityLog('Lead stage updated: '+l.name+' / '+status);render();toast('Workspace lead stage updated')};
function leadDetail(id){let l=db.leads.find(l=>l.id===id);modal('Lead details',`<h2>${esc(l.name)}</h2><span class="badge">${esc(l.product)} · ${esc(normalStage(l.status))}</span><dl class="review-list">${Object.entries(l.details||{phone:l.phone,premium:l.premium,date:l.date}).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${reviewValue(v)}</dd></div>`).join('')}</dl><div class="field"><label>Follow-up notes</label><textarea id="leadNotes" rows="3">${esc(l.notes||'')}</textarea></div><div class="modalfoot">${btn('Save notes',`saveLeadNotes('${id}')`,'check')}${btn('Create quote',`closeModal();openHealthQuote('${id}')`,'file',true)}</div>`)}
function saveLeadNotes(id){db.leads.find(l=>l.id===id).notes=document.querySelector('#leadNotes').value;save();closeModal();toast('Notes saved')}
function contactForm(prospect=false,editId=''){let c=db.contacts.find(c=>c.id===editId)||{};modal(editId?'Edit contact':prospect?'Add prospect':'Add contact',`<p>Duplicate mobiles are checked before saving. Convert the contact to a lead or partner later.</p><form onsubmit="event.preventDefault();saveContactForm(this,'${editId}')"><div class="formgrid">${fieldHTML(F('phone','Mobile','tel',true),c.phone)}${fieldHTML(F('name','Full name','text',true),c.name)}${fieldHTML(F('email','Email','email'),c.email)}${fieldHTML(F('type','Role','select',true,['Lead','Customer','Agent','Prospect']),c.type||(prospect?'Prospect':'Lead'))}${fieldHTML(F('tag','Tag / where you met'),c.tag)}${fieldHTML(F('pan','PAN (optional)'),c.pan)}${fieldHTML(F('birthday','Birthday','date'),c.birthday)}${fieldHTML(F('anniversary','Anniversary','date'),c.anniversary)}${fieldHTML(F('active','Contact status','select',true,['Active','Inactive']),c.active===false?'Inactive':'Active')}${fieldHTML(F('viaAgent','Via agent'),c.viaAgent)}${fieldHTML(F('notes','Notes','textarea'),c.notes)}</div><div class="modalfoot"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">Save contact</button></div></form>`)}
function saveContactForm(form,id){let d=Object.fromEntries(new FormData(form));d.name=d.name.trim();d.phone=normalisePhone(d.phone);if(!d.name||!validPhone(d.phone))return toast('Name and valid mobile are required');let duplicate=db.contacts.find(c=>normalisePhone(c.phone)===d.phone&&c.id!==id);if(duplicate)return toast('A contact with this mobile already exists: '+duplicate.name);d.active=d.active==='Active';if(id)Object.assign(db.contacts.find(c=>c.id===id),d);else db.contacts.unshift({...d,id:uid('CONTACT'),createdAt:new Date().toISOString()});save();closeModal();render();toast('Contact saved')}
contacts=function(){return heading('CONTACTS','My contacts',db.contacts.length+' contacts in your workspace.',btn('Export CSV',"exportRows('contacts')",'download')+btn('Add contact','contactForm()','plus',true))+`<div class="toolbar">${inlineSearch('Search name, mobile, PAN, email…')}</div>${pillTabs(['All','Recent','Leads','Agent Prospects','Active','Inactive','Customers','Via Agent'],contactTab,'setContactTab')}<div id="results">${contactResults()}</div>`}
function setContactTab(t){contactTab=t;render()}
function contactRows(){return db.contacts.filter(c=>[c.name,c.phone,c.email,c.pan,c.tag].join(' ').toLowerCase().includes(query.toLowerCase())&&(contactTab==='All'||contactTab==='Recent'&&Date.now()-new Date(c.createdAt||0).getTime()<30*86400000||contactTab==='Leads'&&c.type==='Lead'||contactTab==='Agent Prospects'&&['Prospect','Agent'].includes(c.type)||contactTab==='Active'&&c.active!==false||contactTab==='Inactive'&&c.active===false||contactTab==='Customers'&&c.type==='Customer'||contactTab==='Via Agent'&&!!c.viaAgent))}
contactResults=function(){let rows=contactRows();return rows.length?`<div class="contactgrid">${rows.map(c=>`<article class="card pad contactcard"><div class="initial">${esc(initials(c.name))}</div><span class="badge">${esc(c.type)} · ${c.active===false?'Inactive':'Active'}</span><h3>${esc(c.name)}</h3><p>${esc(c.phone)}<br>${esc(c.email||'')}<br>${esc(c.tag||'')}</p><div class="actions">${btn('Edit',`contactForm(false,'${c.id}')`,'contact')}${btn('Convert',`convertContact('${c.id}')`,'plus')}</div></article>`).join('')}</div>`:'<section class="card">'+emptyCard('No contacts match','Try another search or add a contact.')+'</section>'}
editContact=id=>contactForm(false,id);contactDetail=function(id){let c=db.contacts.find(c=>c.id===id);if(!c)return;modal('Contact details',`<h2>${esc(c.name)}</h2><p>${esc(c.phone)}<br>${esc(c.email||'')}</p><div class="modalfoot">${btn('Edit',`contactForm(false,'${id}')`)}${btn('Convert',`convertContact('${id}')`,'plus',true)}</div>`)};
function convertContact(id){modal('Convert contact',`<p>Choose the next step for this relationship.</p><div class="actions">${btn('Create insurance lead',`startLead('Health','${id}')`,'shield',true)}${btn('Mark customer',`setContactRole('${id}','Customer')`)}${btn('Agent prospect',`setContactRole('${id}','Prospect')`)}</div>`)}
function setContactRole(id,type){let c=db.contacts.find(c=>c.id===id);c.type=type;if(type==='Prospect'&&!workspace.prospects.some(p=>p.contactId===id)){workspace.prospects.push({id:uid('PROS'),contactId:id,name:c.name,phone:c.phone,status:'Fresh',followUp:'',notes:''});saveWorkspace()}save();closeModal();render();toast('Contact role updated')}
function prospectPage(){let rows=workspace.prospects.filter(p=>(p.name+' '+p.phone).toLowerCase().includes(query.toLowerCase())&&(filter==='All'||filter==='Overdue'&&p.followUp&&p.followUp<dateISO()||filter==='Today'&&p.followUp===dateISO()));return heading('AGENT PROSPECTS','My prospects','Follow callbacks and partnership enquiries.',btn('Add prospect','prospectForm()','plus',true))+`<div class="metrics six">${['Total','Fresh','Callback','Due today','Overdue','Joined'].map(s=>metric(s,s==='Total'?workspace.prospects.length:workspace.prospects.filter(p=>s==='Due today'?p.followUp===dateISO():s==='Overdue'?p.followUp&&p.followUp<dateISO()&&p.status!=='Joined':p.status===s).length,'target','Prospects')).join('')}</div><div class="toolbar">${inlineSearch('Search prospects…')}<select aria-label="Prospect follow-up filter" onchange="filter=this.value;render()">${optionsHTML(['All','Today','Overdue'],filter,false)}</select></div><section class="card tablewrap" id="results"><table><thead><tr><th>Prospect</th><th>Mobile</th><th>Status</th><th>Follow-up</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.phone)}</td><td>${esc(p.status)}</td><td>${esc(p.followUp||'Not scheduled')}</td><td>${btn('Update',`prospectForm('${p.id}')`,'file')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No prospects found</td></tr>'}</tbody></table></section>`}
function prospectForm(id=''){let p=workspace.prospects.find(p=>p.id===id)||{};modal('Agent prospect',`<form onsubmit="event.preventDefault();saveProspect(this,'${id}')"><div class="formgrid">${fieldHTML(F('name','Name','text',true),p.name)}${fieldHTML(F('phone','Mobile','tel',true),p.phone)}${fieldHTML(F('status','Status','select',true,['Fresh','Callback','Joined','Not interested']),p.status||'Fresh')}${fieldHTML(F('followUp','Follow-up date','date'),p.followUp)}${fieldHTML(F('notes','Notes','textarea'),p.notes)}</div><div class="modalfoot"><button class="primary">Save prospect</button></div></form>`)}
function saveProspect(form,id){let d=Object.fromEntries(new FormData(form));if(!validPhone(d.phone))return toast('Enter a valid mobile');if(id)Object.assign(workspace.prospects.find(p=>p.id===id),d);else{if(workspace.prospects.some(p=>normalisePhone(p.phone)===normalisePhone(d.phone)))return toast('This prospect already exists');workspace.prospects.push({...d,id:uid('PROS')})}saveWorkspace();closeModal();render();toast('Prospect saved')}
